function model(p) {
  // 14 data governance terms in three themes, joined by typed links that read as sentences (source, label, target).
  const THEMES = ['People', 'Processes', 'Safeguards'];
  const TERMS = [
    ['owner', 'Data owner', 0, 'The business leader accountable for a data set, who decides how it may be used.'],
    ['steward', 'Data steward', 0, 'The day-to-day caretaker who keeps definitions, quality and catalog entries in order.'],
    ['pii', 'PII', 0, 'Personally identifiable information: any detail that can identify a person.'],
    ['consent', 'Consent', 0, 'A person\'s recorded permission to use their data for a stated purpose.'],
    ['catalog', 'Data catalog', 1, 'A searchable inventory of data sets, so people can find and understand them.'],
    ['metadata', 'Metadata', 1, 'Data about data: names, owners, definitions, formats and dates.'],
    ['lineage', 'Lineage', 1, 'The path data takes from source to report, including every step that changed it.'],
    ['quality', 'Data quality', 1, 'How accurate, complete and up to date data is for the job it has to do.'],
    ['master', 'Master data', 1, 'The core shared records a business runs on, such as customers, products and suppliers.'],
    ['golden', 'Golden record', 1, 'The single trusted version of a customer or product, merged from duplicate records.'],
    ['classification', 'Classification', 2, 'Labelling data by sensitivity, such as public, internal or confidential.'],
    ['access', 'Access control', 2, 'The rules that decide who can see or change which data.'],
    ['retention', 'Retention policy', 2, 'The rule for how long data is kept and when it must be deleted.'],
    ['audit', 'Audit trail', 2, 'A tamper-evident log of who accessed or changed data, and when.']
  ];
  const LINKS = [
    ['owner', 'steward', 'appoints'], ['owner', 'access', 'approves'], ['owner', 'retention', 'sets'],
    ['steward', 'catalog', 'maintains'], ['steward', 'quality', 'monitors'],
    ['catalog', 'metadata', 'organises'], ['metadata', 'master', 'describes'], ['metadata', 'lineage', 'captures'],
    ['metadata', 'classification', 'carries'], ['lineage', 'quality', 'traces issues in'],
    ['master', 'golden', 'is merged into'], ['quality', 'golden', 'underpins'],
    ['classification', 'pii', 'flags'], ['classification', 'access', 'drives'], ['access', 'pii', 'protects'],
    ['pii', 'consent', 'needs'], ['consent', 'retention', 'shapes'], ['access', 'audit', 'is logged in'], ['audit', 'consent', 'records']
  ];
  const CENTRAL = ['steward', 'owner', 'metadata', 'classification', 'access'];
  const fi = Math.max(0, Math.min(CENTRAL.length, Math.round(p.focus)));
  const focusId = fi > 0 ? CENTRAL[fi - 1] : null;
  const showLabels = Math.round(p.showLabels) === 1;
  // Playback: terms theme by theme, then the links one by one, then the focus step.
  const themeStart = [0, 1.9, 4.6], gap = 0.42, linksStart = 6.6, linkGap = 0.16, focusAt = 10.4, duration = 12;
  const nb = new Set();
  LINKS.forEach(([s, t]) => { if (s === focusId) nb.add(t); if (t === focusId) nb.add(s); });
  const byId = {}, counts = [0, 0, 0];
  const terms = TERMS.map(([id, name, g, def]) => {
    const k = counts[g]++;
    const t = { id, name, theme: THEMES[g], themeIndex: g, def, revealAt: +(themeStart[g] + k * gap).toFixed(2),
      isFocus: id === focusId, isNeighbour: nb.has(id), highlighted: id === focusId || nb.has(id), degree: 0 };
    byId[id] = t;
    return t;
  });
  const links = LINKS.map(([s, t, label], i) => {
    const a = byId[s], b = byId[t];
    if (a) a.degree++;
    if (b) b.degree++;
    return { source: s, target: t, label, sentence: (a ? a.name : s) + ' ' + label + ' ' + (b ? b.name : t),
      revealAt: +(linksStart + i * linkGap).toFixed(2),
      crossTheme: !!(a && b && a.themeIndex !== b.themeIndex), highlighted: !!focusId && (s === focusId || t === focusId) };
  });
  const cross = links.filter(l => l.crossTheme).length;
  const f = focusId ? byId[focusId] : null;
  const nbNames = terms.filter(t => t.isNeighbour).map(t => t.name);
  const list = nbNames.length > 1 ? nbNames.slice(0, -1).join(', ') + ' and ' + nbNames[nbNames.length - 1] : nbNames.join('');
  const summary = f
    ? f.name + ' links directly to ' + nbNames.length + ' terms: ' + list + '.'
    : terms.length + ' terms and ' + links.length + ' links; ' + cross + ' links cross between themes, so the vocabulary works as one system.';
  return {
    themes: THEMES, terms, links, focusId, focusTerm: f ? f.name : null, neighbourCount: nbNames.length,
    crossThemeLinks: cross, showLabels, themeStart, linksStart, focusAt, duration,
    markers: themeStart.concat([linksStart, focusAt]), summary
  };
}

