function check(p) {
  const m = model(p);
  const ids = new Set(m.terms.map(t => t.id));
  const badLinks = m.links.filter(l => !ids.has(l.source) || !ids.has(l.target) || l.source === l.target);
  const linked = new Set();
  m.links.forEach(l => { linked.add(l.source); linked.add(l.target); });
  const orphans = m.terms.filter(t => !linked.has(t.id)).map(t => t.name);
  // Recompute the focus neighbourhood from the links and compare it with what the model highlights.
  const expected = new Set();
  if (m.focusId) {
    expected.add(m.focusId);
    m.links.forEach(l => { if (l.source === m.focusId) expected.add(l.target); if (l.target === m.focusId) expected.add(l.source); });
  }
  const got = m.terms.filter(t => t.highlighted).map(t => t.id);
  const focusOk = got.length === expected.size && got.every(id => expected.has(id)) &&
    m.links.every(l => l.highlighted === (!!m.focusId && (l.source === m.focusId || l.target === m.focusId)));
  const pass = ids.size === m.terms.length && badLinks.length === 0 && orphans.length === 0 && focusOk;
  return {
    pass,
    detail: m.links.length + ' links between ' + ids.size + ' defined terms, ' + badLinks.length + ' pointing at unknown terms, ' +
      orphans.length + ' terms without a link' + (orphans.length ? ' (' + orphans.join(', ') + ')' : '') +
      (m.focusId ? '; focus on ' + m.focusTerm + ' highlights ' + got.length + ' terms, expected ' + expected.size + ' (the term plus ' + (expected.size - 1) + ' direct neighbours).'
        : '; no focus term, ' + got.length + ' terms highlighted.')
  };
}
